// 2. Separate the timetable and summary sections
// The AI's output should follow the structure we defined in the prompt
const [timetableText] =[$('AI Agent').first().json.output['TripTimeTable'].table];
// 3. Parse the Timetable Markdown into a JSON Array
const timetableRows = timetableText.trim().split('\n').filter(row => row.startsWith('|')).slice(2);
const timetableData = timetableRows.slice(0,timetableRows.length - 1).map(row => {
  const [empty, Day, Time, Activity, Location] = row.split('|').map(cell => cell.trim());
  return { Day, Time, Activity, Location };
});

// Return the structured data for the next node
return timetableData.map(row => ({ json: row }));

// 1. Separate the timetable and summary sections
// The AI's output should follow the structure we defined in the prompt
const [summaryText] = [$('AI Agent').first().json.output.Summary];

// 2. Create the final JSON object for the Spreadsheet File node
const sheetsData = {
  Summary: summaryText.trim()
};

// Return the structured data for the next node
return [{ json: sheetsData }];

parameters.inputSchema:
{
"title": "Travel Itinerary Schema",
  "type": "object",
  "properties": {
    "filename": {
      "type": "string",
      "description": "The name of the location or destination for the trip."
    },
    "startDate": {
      "type": "string",
      "format": "date",
      "description": "The starting date of the trip."
    },
    "endDate": {
      "type": "string",
      "format": "date",
      "description": "The ending date of the trip."
    },
    "fullListOfCities": {
      "type": "array",
      "description": "A comprehensive list of all cities to be visited during the trip.",
      "items": {
        "type": "string"
      }
    },
    "Summary": {
      "type": "string",
      "description": "A brief summary of the entire trip."
    },
    "TripTimeTable": {
      "type": "object",
      "description": "A markdown table representing the full trip schedule.",
      "properties": {
        "type": {
          "type": "string",
          "enum": ["Markdown_table"],
          "description": "The format type of the timetable."
        },
        "table": {
          "type": "string",
          "description": "A complete and comprehensive daily travel timetable in MARKDOWN TABLE FORMAT for the entire duration of the vacation. The table MUST contain the following four columns: Date, Time, Activity, and Location. Each row MUST represent a unique activity or event. The entire schedule, from the start date to the end date, must be included in a single table. Do not truncate the table. The table should begin with the header row followed by the separator line. For example: | Date | Time | Activity | Location |\\n|---|---|---|---|\\n| 01/01/2023 | 09:00 AM | Breakfast | Hotel Restaurant |"
        }
      },
      "required": [
        "type",
        "table"
      ]
    }
  },
  "required": [
    "filename",
    "startDate",
    "endDate",
    "fullListOfCities",
    "Summary",
    "TripTimeTable"
  ]
}
